H('9. Appendices',br=True)
H('9.1 Development criteria',2)
P('Table 5 lists the ten inherited numerical criteria, applied separately to original and social-style views. They are project-defined requirements, not an external certification standard. Automatic coverage and uncertainty are complementary, and several other metrics are correlated. The separate rule against newly missing any reference-detected AI image failed for E92. Coverage and uncertainty here describe each view separately; they are not the paired website outcomes in Section 4.5.6.')
T(5,'E92 numerical development checks and their measured values.',['Criterion','Requirement','Original','Social'],[['Valid-score coverage','100%','100%','100%'],['ROC-AUC','≥0.90','0.9998','0.9942'],['Balanced accuracy','≥85%','99.69%','95.31%'],['Pooled real false alerts','≤10%','0.00%','8.75%'],['Worst real source','≤20%','0.00%','18.75%'],['Pooled AI detection','≥80%','99.38%','99.38%'],['Worst AI source','≥60%','98.75%','98.75%'],['Automatic coverage','≥80%','98.75%','98.44%'],['Accuracy when automatic','≥95%','99.68%','95.24%'],['Uncertain fraction','≤20%','1.25%','1.56%']],[2.65,1.17,1.23,1.22])
